use topcoat::{
    Result,
    context::{Cx, context},
    router::{Slot, href, layout},
    view::{NodeViewParts, PartsWriter, View, class, view},
};

use crate::{pages, state::Site};
use vg360_guard::policy::Status;

/// Markup generated by this server (SVG plans, charts). Never wraps user input.
pub struct Trusted(pub String);

impl NodeViewParts for Trusted {
    fn into_view_parts(self, _cx: &Cx, parts: &mut PartsWriter<'_>) {
        parts.push_string_unescaped(self.0);
    }
}

pub fn guard_tone(s: Status) -> &'static str {
    match s {
        Status::Ok => "ok",
        Status::Realigning => "warn",
        Status::Moved | Status::Blocked | Status::ViewLost => "bad",
    }
}

#[layout("/")]
pub async fn shell(cx: &Cx, slot: Slot<'_>) -> Result<impl View> {
    let site = context::<Site>(cx);
    let nav = [
        (href!(pages::overview).resolve(cx), href!(pages::overview).is_current(cx), "Overview"),
        (href!(pages::live).resolve(cx), href!(pages::live).is_current(cx), if site.live.is_running() { "Live ●" } else { "Live" }),
        (href!(pages::rules).resolve(cx), href!(pages::rules).is_current(cx), "Rules & evidence"),
        (href!(pages::twin).resolve(cx), href!(pages::twin).is_current(cx), "Site twin"),
        (href!(pages::training).resolve(cx), href!(pages::training).is_current(cx), "Models & training"),
        (href!(pages::settings).resolve(cx), href!(pages::settings).is_current(cx), "Settings"),
    ];
    let alarms = site.cams.iter().filter(|c| c.guard != Status::Ok).count();
    Ok(view! {
        <!DOCTYPE html>
        <html lang="en">
            <head>
                <meta charset="utf-8">
                <meta name="viewport" content="width=device-width, initial-scale=1">
                <title>"VisionGuard360 · " (site.name)</title>
                <link rel="stylesheet" href="/app.css">
            </head>
            <body>
                <header class="top">
                    <div class="brand"><span class="mark">"VG"</span>"VisionGuard360"<small>"CPU edge analytics"</small></div>
                    <nav>
                        for (link, current, label) in nav {
                            <a href=(link) class=(class!("nav", "on" if current))>(label)</a>
                        }
                    </nav>
                    <div class="site">
                        <span class="dot live"></span>(site.name)
                        if alarms > 0 {
                            <span class="pill bad">(alarms) " guard alarm"</span>
                        }
                    </div>
                </header>
                <main>(slot)</main>
                <footer>"Rust · Topcoat 0.12 · inference: " (if cfg!(feature = "ort") { "ONNX Runtime (CPU)" } else { "tract (pure-Rust ONNX, CPU)" }) " · camera cards show sample data from the notebook simulation; the Live page runs the real pipeline"</footer>
            </body>
        </html>
    })
}
